ruleSearch.bookList:
@js:(function(){
  // 作品ID搜索渠道：输入 id:1234567890123456789 或 纯 15-20 位数字
  var s0='';
  try{
    var mq=String(baseUrl).match(/[?&]q=([^&]*)/);
    if(mq){s0=decodeURIComponent(mq[1]);}
  }catch(e){}
  s0=String(s0).replace(/^\s+|\s+$/g,'');
  var idv='';
  if(/^id[:：]\s*[0-9]{1,20}$/i.test(s0)){
    idv=s0.replace(/^id[:：]\s*/i,'');
  }else if(/^[0-9]{15,20}$/.test(s0)){
    idv=s0;
  }
  if(idv){
    var one=null;
    try{one=FQ_bookById(java,source,idv);}catch(e){one=null;}
    if(one){return [JSON.stringify(one)];}
    return [];
  }
  var items=[];
  try{
    var d=JSON.parse(String(result));
    items=(d.data&&d.data.ret_data)?d.data.ret_data:[];
  }catch(e){items=[];}
  if(items.length===0){
    var kw='';
    var off=0;
    try{
      var m=String(baseUrl).match(/[?&]q=([^&]*)/);
      if(m){kw=decodeURIComponent(m[1]);}
      var mo=String(baseUrl).match(/[?&]offset=(\d+)/);
      if(mo){off=parseInt(mo[1],10)||0;}
    }catch(e){}
    if(kw||off===0){
      var u=String(baseUrl).replace('aid=13','aid=1967');
      var alt=[];
      if(u!==String(baseUrl)){
        try{
          var d2=JSON.parse(String(java.ajax(u)));
          alt=(d2.data&&d2.data.ret_data)?d2.data.ret_data:[];
        }catch(e){alt=[];}
      }
      for(var j=0;j<alt.length;j++){
        var t2=String(alt[j].title||'').split('<em>').join('').split('</em>').join('');
        var a2=String(alt[j].author||'');
        if(kw&&t2.indexOf(kw)<0&&a2.indexOf(kw)<0){continue;}
        items.push(alt[j]);
      }
    }
  }
  var out=[];
  for(var i=0;i<items.length;i++){
    var it=items[i];
    var t=String(it.title||'').split('<em>').join('').split('</em>').join('');
    out.push(JSON.stringify({name:t,author:String(it.author||''),kind:String(it.category||''),intro:String(it.abstract||''),coverUrl:String(it.thumb_url||''),bookUrl:'https://fanqienovel.com/page/'+String(it.book_id)}));
  }
  return out;
})()

ruleToc.chapterList:
@js:(function(){
  var m=String(baseUrl).match(/([0-9]{15,})/);
  var bid=m?m[1]:'';
  if(!bid){throw new Error('无效书籍ID');}
  var base='ac=wifi&channel=xiaomi_1967_64&aid=1967&app_name=novelapp&version_code=65132&version_name=6.5.1.32&device_platform=android&os=android&ssmix=a&device_type=FRD-AL10&device_brand=honor&language=zh&os_api=28&os_version=9&manifest_version_code=65132&resolution=1080*1920&dpi=480&update_version_code=65132&pv_player=65132&need_personal_recommend=1&player_so_load=1&is_android_pad_screen=0&host_abi=arm64-v8a&dragon_device_type=phone&compliance_status=0';
  var raw=FQ_api(java,source,'/reading/bookapi/directory/all_items/v','book_type=0&item_data_list_md5=&catalog_data_md5=&book_id='+bid+'&book_info_md5=&need_version=true&'+base);
  var d=JSON.parse(raw);
  var dd=d.data||{};
  var dd2=(dd&&dd.data)?dd.data:dd;
  function GV(n){var v=dd[n];if(v!==undefined&&v!==null)return v;return dd2[n];}
  var out=[],seen={},volShown=false;
  function vid(c){return String(c.itemId||c.item_id||c.chapter_id||c.id||c.catalog_id||'');}
  function vtitle(c,idx){return String(c.title||c.chapter_title||c.catalog_title||c.name||('第'+(idx+1)+'章'));}
  function emitVol(vol){vol=String(vol||'').trim();if(vol&&vol!=='正文'&&!seen[vol]){seen[vol]=1;volShown=true;out.push(JSON.stringify({name:vol,url:'',isVolume:true}));}}
  function emitCh(c,idx){var id=vid(c);if(!id)return;out.push(JSON.stringify({name:vtitle(c,idx),url:'https://fanqienovel.com/page/'+bid+String.fromCharCode(35)+id,isVolume:false}));}
  function finish(arr){if(!volShown&&arr.length){arr.unshift(JSON.stringify({name:'第一卷：默认',url:'',isVolume:true}));}return arr;}
  // 卷名：优先 chapterListWithVolume（真实分卷）；兼容 d.data 与 d.data.data 两层嵌套
  var grouped=GV('chapterListWithVolume');
  var cats=GV('item_data_list');if(!cats||!cats.length)cats=GV('catalog_data')||[];
  if(Array.isArray(grouped)&&grouped.length){
    var flatHasVol=false;
    for(var k=0;k<cats.length;k++){var v=String(cats[k].volume_name||cats[k].volumeName||'').trim();if(v&&v!=='正文'){flatHasVol=true;break;}}
    if(!flatHasVol){
      for(var g=0;g<grouped.length;g++){
        var vol=grouped[g],chs=null,defV='';
        if(Array.isArray(vol)){chs=vol;if(chs[0])defV=String(chs[0].volume_name||chs[0].volumeName||'').trim();}
        else if(vol&&typeof vol==='object'){defV=String(vol.volume_name||vol.volumeName||'').trim();chs=vol.chapterList||vol.chapter_list||vol.chapters||vol.item_data_list||[];}
        else continue;
        if(!chs||!chs.length)continue;
        for(var i=0;i<chs.length;i++){
          var c=chs[i];
          var cv=String(c.volume_name||c.volumeName||'').trim();
          emitVol(cv||defV);
          emitCh(c,i);
        }
      }
      if(out.length)return finish(out);
    }
  }
  // 扁平回退：直接读 item_data_list / catalog_data 每章 volume_name
  if(!cats.length){throw new Error('本书没有可读文本目录（可能是听书专辑/漫画/已下架），请换源');}
  for(var i=0;i<cats.length;i++){var c=cats[i];emitVol(c.volume_name||c.volumeName);emitCh(c,i);}
  return finish(out);
})()

