ruleToc.preUpdateJs:
eval(String(source.loginUrl));
var sourceUL = GetUL();
if (!String(book.bookUrl).includes(sourceUL)) {
  book.bookUrl = String(book.bookUrl).replace(/https?:\/\/[^\/]+/,sourceUL);
  book.tocUrl = String(book.tocUrl).replace(/https?:\/\/[^\/]+/,sourceUL);
  java.toast("\n检测到切换源站，已更新目录链接。");
  java.refreshTocUrl();
}

