        }
    };
}

function formatDate(input, fmt) {
    if (fmt === undefined) fmt = 'YYYY-MM-DD HH:mm:ss';
    var date = (input instanceof Date) ? input : new Date(input);
    if (isNaN(date.getTime())) return '';

    function pad(n) {
        var s = String(n);
        return s.length < 2 ? '0' + s : s;
    }

    var map = {
        YYYY: date.getFullYear(),
        MM: pad(date.getMonth() + 1),
        DD: pad(date.getDate()),
        HH: pad(date.getHours()),
        mm: pad(date.getMinutes()),
        ss: pad(date.getSeconds())
    };

    return fmt.replace(/YYYY|MM|DD|HH|mm|ss/g, function(m) {
        return map[m];
    });
}

function Env() {
    var java = this.java;
    var source = this.source;
    try {
        java.qread();
        return 4;
