            // novel.seriesId = novel.seriesId
            // novel.seriesTitle = novel.seriesTitle

            // 兼容详情页
            if (novel.content) {
                if (novel.series) {
                    novel.seriesId = novel.series.id
                    novel.seriesTitle = novel.series.title
                }
                novel.textCount = novel.length = novel.content.length
            }

            // 单篇添加更多信息
