                novel.tags.unshift("单本")
                novel.textCount = novel.length
                novel.latestChapter = novel.title
                novel.detailedUrl = urlNovelDetailed(novel.id)
            }

            // 搜索、详情：系列添加更多信息
            if (novel.seriesId) {
